# @beacon[
#   id=auto-beacon@AmbiguousMarkdownNodeError-amb3,
#   role=AmbiguousMarkdownNodeError,
#   slice_labels=nexus-md-header-path,nexus-path-resolution-logic,handle-resolution,
#   kind=ast,
# ]
class AmbiguousMarkdownNodeError(NetworkError):
    """A Markdown node's MD_PATH matched multiple headings and could not be
    auto-disambiguated by sibling ordinal.

    Subclasses NetworkError so existing ``except NetworkError`` sites keep
    treating it as a (non-fatal) resolution failure, but it additionally
    carries ``file_path`` and a structured ``candidates`` list (each
    ``{"occurrence": int, "line": int, "hint": str}``) so the F9 handler can
    surface an honest picker/error to the widget instead of a silent wrong
    jump. See get_snippet_for_md_path Option C disambiguation.
    """

    def __init__(self, message: str, *, file_path: str | None = None, candidates=None):
        super().__init__(message)
        self.file_path = file_path
        self.candidates = candidates or []


# @beacon[
#   id=auto-beacon@_compute_same_name_sibling_ordinal-amb4,
#   role=_compute_same_name_sibling_ordinal(nodes_by_id, node),
#   slice_labels=nexus-md-header-path,ra-workflowy-cache,nexus-path-resolution-logic,
#   kind=ast,
# ]
def _compute_same_name_sibling_ordinal(
    nodes_by_id: dict[str, dict[str, Any]],
    node: dict[str, Any] | None,
) -> int | None:
    """Return the 1-based ordinal of ``node`` among same-name siblings.

    Option C duplicate-sibling disambiguation. Given the /nodes-export cache
    (``nodes_by_id``) and a target node, find all children of the SAME parent
    whose (decoration/tag-stripped) name matches the target's name, order them
    by the canonical Workflowy ``priority`` field (NOT raw JSON order, which is
    unreliable), and return the target's 1-based position in that list.

    Returns None when:
      - there is no parent (root-level), or
      - the node is the ONLY child with that name (no ambiguity, so no ordinal
        is needed; the resolver will find a unique match anyway).

    The returned ordinal corresponds to disk document order because F12
    reconcile keeps Workflowy sibling order == on-disk heading order.
    """
    if not isinstance(node, dict):
        return None
    parent_id = node.get("parent_id") or node.get("parentId")
    if not parent_id:
        return None
    target_id = str(node.get("id") or "")
    if not target_id:
        return None

    def _clean_name(n: dict[str, Any]) -> str:
        raw = str(n.get("name") or n.get("nm") or "")
        # Drop the trailing #tag / trident / marker decoration region via the
        # ONE canonical emoji-aware splitter (returns just its base), so this
        # name-matcher agrees with every tag tool / reconcile strip on where
        # the trailing region ends. (Local import mirrors the other
        # split_name_and_tags call sites in this module -- avoids the
        # documented module-load cycle.)
        try:
            from nexus_map_codebase import split_name_and_tags  # type: ignore[import-not-found]
            cleaned, _tags = split_name_and_tags(raw)
        except Exception:
            toks = raw.split()
            while toks and (toks[-1].startswith("#") or toks[-1].startswith("\U0001fa9a") or toks[-1] == "\U0001f531"):
                toks.pop()
            cleaned = " ".join(toks).strip()
        # Also strip a leading run of non-alnum decoration (emoji/bullets).
        # (Leading-decoration strip is THIS matcher's own concern; the
        # canonical splitter deliberately owns only the TRAILING region.)
        i = 0
        while i < len(cleaned) and not (cleaned[i].isalnum() or cleaned[i] in {"_", "$", "[", "("}):
            i += 1
        return cleaned[i:].strip() or cleaned

    target_name = _clean_name(node)

    siblings = [
        n for n in nodes_by_id.values()
        if str(n.get("parent_id") or n.get("parentId") or "") == str(parent_id)
    ]
    # Canonical Workflowy order is by 'priority' ascending (JSON order is not).
    siblings.sort(key=lambda c: c.get("priority", 999999))
    same_name = [s for s in siblings if _clean_name(s) == target_name]
    if len(same_name) <= 1:
        return None  # unique by name; resolver needs no ordinal
    ids = [str(s.get("id") or "") for s in same_name]
    try:
        return ids.index(target_id) + 1
    except ValueError:
        return None


# ===========================================================================
# Lightning Rod beacon mutation -- PLAN SEAM (SPEC v5 §5)
# ===========================================================================
#
# TWO DISTINCT ARTIFACTS share the ONE computation below:
#   * PREFLIGHT (Phase C) -- the side-effect-free batch gate
#     (preflight_beacon_write_from_node; include_fingerprint=False);
#   * EXECUTABLE PLAN (Phase D step 1) -- regenerated JUST-IN-TIME against
#     the current file state (plan_beacon_write_from_node;
#     include_fingerprint=True, carrying the raw-bytes sha256 CAS).
#
# DISK TRUTH + CACHED NOTE (invariant 4): beacon state is decided from the
# on-disk parse plus the /nodes-export cache; never from live API fetches.

_BEACON_LANGUAGE_BY_EXT = {
    ".py": "python",
    ".js": "js_ts",
    ".jsx": "js_ts",
    ".ts": "js_ts",
    ".tsx": "js_ts",
    ".vue": "vue",
    ".md": "markdown",
    ".markdown": "markdown",
    ".sql": "sql",
    ".yml": "yaml",
    ".yaml": "yaml",
    ".sh": "shell",
    ".bash": "shell",
}

_BEACON_LANGUAGE_HELPER_NAME = {
    "python": "update_beacon_from_node_python",
    "js_ts": "update_beacon_from_node_js_ts",
    "vue": "update_beacon_from_node_vue",
    "markdown": "update_beacon_from_node_markdown",
    "sql": "update_beacon_from_node_sql",
    "yaml": "update_beacon_from_node_yaml",
    "shell": "update_beacon_from_node_shell",
}

def _import_cartographer_module():
    """Import nexus_map_codebase via the repo-root walk-up (the documented
    module-load cycle: foundation code must import it lazily)."""
    import importlib

    client_dir = os.path.dirname(os.path.abspath(__file__))
    wf_mcp_dir = os.path.dirname(client_dir)
    mcp_servers_dir = os.path.dirname(wf_mcp_dir)
    project_root = os.path.dirname(mcp_servers_dir)
    if project_root not in sys.path:
        sys.path.insert(0, project_root)
    return importlib.import_module("nexus_map_codebase")


# @beacon[
#   id=auto-beacon@_resolve_beacon_target_from_cache-rbtc,
#   role=_resolve_beacon_target_from_cache(nodes_by_id, node_id),
#   slice_labels=beacon-writeback,
#   kind=ast,
#   comment=Shared cache path/FILE/language adapter for beacon writers and plan/commit seams; also projects ordered source-derived AST sibling signatures for the physical selector to validate as a current twin witness without granting authority to a cache ordinal alone.,
# ]
def _resolve_beacon_target_from_cache(nodes_by_id: dict, node_id: str) -> dict:
    """Resolve a node's beacon-write target from the /nodes-export cache.

    Shared path/identity extraction, not physical target selection. Ordered
    sibling signatures are evidence only; the pure selector checks them against
    the current source. Never raises for ordinary resolution failures.
    """
    node = nodes_by_id.get(str(node_id))
    if not node:
        return {
            "success": False,
            "error_kind": "node_not_found",
            "error": f"node {node_id!r} not found in /nodes-export cache",
        }

    current_id = str(node_id)
    visited: set[str] = set()
    file_node = None
    while current_id and current_id not in visited:
        visited.add(current_id)
        n = nodes_by_id.get(current_id)
        if not n:
            break
        n_note = n.get("note") or n.get("no") or ""
        if isinstance(n_note, str) and _extract_path_header_from_note(n_note) is not None:
            file_node = n
        if file_node is not None:
            break
        parent_id_val = n.get("parent_id") or n.get("parentId")
        current_id = str(parent_id_val) if parent_id_val else None

    if not file_node:
        return {
            "success": False,
            "error_kind": "no_enclosing_file_node",
            "error": (
                "could not find ancestor FILE node with Path:/Root: "
                f"for node {node_id!r} (visited_chain={list(visited)})"
            ),
        }

    file_note = file_node.get("note") or file_node.get("no") or ""
    source_path = parse_path_or_root_from_note(str(file_note))
    if not source_path:
        return {
            "success": False,
            "error_kind": "file_node_missing_path",
            "error": f"ancestor FILE node missing Path:/Root: for node {node_id!r}",
        }

    try:
        resolved_path = resolve_cartographer_path_from_node(
            node_id=str(file_node.get("id")),
            nodes_by_id=nodes_by_id,
        )
    except Exception as e:  # noqa: BLE001
        return {
            "success": False,
            "error_kind": "path_resolution_failed",
            "error": (
                "failed to resolve Cartographer Path:/Root: to absolute path "
                f"for node {node_id!r}: {e}"
            ),
        }

    source_path = str(resolved_path.get("abs_path") or "")
    ext = os.path.splitext(source_path)[1].lower()
    language = _BEACON_LANGUAGE_BY_EXT.get(ext)

    try:
        cartographer = _import_cartographer_module()
    except Exception as e:  # noqa: BLE001
        return {
            "success": False,
            "error_kind": "cartographer_import_failed",
            "error": f"failed to import nexus_map_codebase: {e}",
        }

    return {
        "success": True,
        "node": node,
        "file_node": file_node,
        "file_node_id": str(file_node.get("id")),
        "source_path": source_path,
        "ext": ext,
        "language": language,
        "cartographer": cartographer,
        "twin_witness": cartographer._beacon_cache_twin_witness(nodes_by_id, node),
    }


# @beacon[
#   id=auto-beacon@_extract_note_beacon_comment-dan2,
#   role=_extract_note_beacon_comment,
#   slice_labels=beacon-writeback,
#   kind=ast,
#   comment=Thin projection of decoded comment values from scoped header records; span/context/docstring text is never a fallback field.,
# ]
def _extract_note_beacon_comment(note: str) -> "str | None":
    """Project unambiguous decoded header comment text for the one resolver."""
    from beacon_mutation_contract import parse_beacon_note_metadata
    values = {v["value"] for r in parse_beacon_note_metadata(note)
              for v in r["occurrences"] if v["key"] == "comment"}
    return next(iter(values)) if len(values) == 1 else None


# @beacon[
#   id=auto-beacon@_canonical_label_tokens-88od,
#   role=_canonical_label_tokens,
#   slice_labels=beacon-writeback,
#   kind=ast,
# ]
def _canonical_label_tokens(carto: Any, raw: Any) -> list:
    """Canonicalize a raw label string/list to the writer's canonical tokens."""
    canon = carto._canonicalize_slice_labels(raw or "", None)
    return [t for t in str(canon or "").split(",") if t]


def _is_carto_virtual_group_note(note: Any) -> bool:
    """True only for a synthetic Cartographer virtual-group node's note.

    A group note STARTS with its ``CARTOGRAPHER_VIRTUAL_GROUP: <language>``
    header line (``group_outline_by_carto_markers`` emits it first). A plain
    substring test misfires on any beacon node whose note merely QUOTES that
    marker -- e.g. a span beacon whose SPAN TEXT contains the group-parsing
    code itself (``carto-virtual-groups@identity-and-grouping``), which made
    ``tags.remove`` / ``tags.ensure`` silently return noop (Manager-Session-088).
    """
    for line in str(note or "").splitlines():
        if line.strip():
            return line.lstrip().startswith("CARTOGRAPHER_VIRTUAL_GROUP:")
    return False


# @beacon[
#   id=auto-beacon@_compute_beacon_write_plan-cbwp,
#   role=_compute_beacon_write_plan(nodes_by_id, node_id, operation, mode, include_fingerprint),
#   slice_labels=beacon-writeback,
#   kind=ast,
#   comment=Thin cache/snapshot adapter delegates selection planning and comments unchanged and hands that same snapshot to the beacon evidence projector for findings field diagnostics and physical witnesses; never fingerprints a later read.,
# ]
def _compute_beacon_write_plan(
    nodes_by_id: dict,
    node_id: str,
    operation: Any,
    mode: str,
    *,
    include_fingerprint: bool,
) -> "BeaconWritePlan":
    """Cache/IO adapter to the shared physical selector and delta planner.

    Performs ZERO disk writes. The cache and one binary source observation
    supply the plan; parsing and executable fingerprint share those bytes.
    Target and label decisions belong exclusively to the pure nmc planner;
    this seam retains shared semantic comment resolution and hands the existing
    snapshot to the common findings projector, without another read or policy.
    """

    def _fail(error: str, error_kind: str, **fields: Any) -> "BeaconWritePlan":
        base: dict[str, Any] = dict(
            success=False,
            planned_operation=None,
            node_id=str(node_id),
            target_key=None,
            cached_name="",
            intended_name="",
            write_intent=None,
            occurrence=None,
            file_node_id=None,
            source_path=None,
            language=None,
            beacon_id=None,
            note_comment=None,
            disk_comment=None,
            comment_outcome=None,
            resolved_comment=None,
            intended_slice_labels=(),
            source_sha256=None,
            error=error,
            error_kind=error_kind,
        )
        base.update(fields)
        return BeaconWritePlan(**base)

    requested_tags = [
        str(t).strip()
        for t in (getattr(operation, "tags", None) or ())
        if str(t).strip()
    ]
    intent = getattr(operation, "comment", None)
    if not isinstance(intent, BeaconCommentIntent):
        intent = BeaconCommentIntent.preserve()

    # 1) Read the node from the /nodes-export cache (name + note). No live fetch.
    node = nodes_by_id.get(str(node_id))
    if not node:
        return _fail(
            f"node {node_id!r} not found in /nodes-export cache",
            "node_not_found",
        )
    cached_name = str(node.get("name") or "")
    cached_note = str(node.get("note") or node.get("no") or "")

    # 2) VIRTUAL-GROUP GUARD (mirrors update_beacon_from_node's early return).
    if _is_carto_virtual_group_note(cached_note):
        return BeaconWritePlan(
            success=True,
            planned_operation="noop",
            node_id=str(node_id),
            target_key=None,
            cached_name=cached_name,
            intended_name=cached_name,
            write_intent=BeaconWriteIntent(comment=intent, source="lightning_rod"),
            occurrence=None,
            file_node_id=None,
            source_path=None,
            language=None,
            beacon_id=None,
            note_comment=None,
            disk_comment=None,
            comment_outcome="preserve",
            resolved_comment=None,
            intended_slice_labels=(),
            source_sha256=None,
            noop_reason="virtual_group",
        )

    # 3) Shared target resolution (ONE path-resolution implementation).
    target = _resolve_beacon_target_from_cache(nodes_by_id, node_id)
    if not target.get("success"):
        return _fail(
            target.get("error") or "target resolution failed",
            target.get("error_kind") or "target_resolution_failed",
            cached_name=cached_name,
        )
    carto = target["cartographer"]
    source_path = target["source_path"]
    language = target["language"]
    file_node_id = target["file_node_id"]
    if language is None:
        return _fail(
            f"unsupported extension {target['ext']!r} for beacon mutation",
            "operation_not_supported_for_target",
            cached_name=cached_name,
            file_node_id=file_node_id,
            source_path=source_path,
        )

    # 4) PURE disk parse + note-side metadata.
    try:
        snapshot = carto.read_source_snapshot(source_path)
        structures = carto._beacon_selection_structures(snapshot, language)
    except Exception as e:  # noqa: BLE001
        return _fail(
            f"failed_to_read_file: {e}",
            "disk_read_failed",
            cached_name=cached_name,
            file_node_id=file_node_id,
            source_path=source_path,
            language=language,
        )

    note_beacon_id_value = (carto._extract_beacon_id_from_note(cached_note) or "").strip()
    ast_qualname = (carto._extract_ast_qualname_from_note(cached_note) or "").strip() or None
    md_path = carto._extract_md_path_from_note(cached_note) if language == "markdown" else None
    note_comment = _extract_note_beacon_comment(cached_note)
    occurrence = (
        _compute_same_name_sibling_ordinal(nodes_by_id, node)
        if language == "markdown"
        else None
    )

    selection_target = {"language": language, "ast_qualname": ast_qualname, "md_path": md_path,
                        "occurrence": occurrence, "note_beacon_id": note_beacon_id_value,
                        "twin_witness": target.get("twin_witness"),
                        "operation": "delta_ensure" if mode == "ensure_beacons" else "delta_remove"}
    selection = carto.select_beacon_block_for_node(snapshot, structures, selection_target)
    selected = selection.get("block")

    # 6) Disk-side metadata of the selected block.
    disk_beacon_id = None
    disk_comment = None
    if selected is not None:
        sel_b = selected.get("beacon") or selected["record"]["fields"]
        disk_beacon_id = (sel_b.get("id") or "").strip() or None
        disk_comment = sel_b.get("comment")

    requested_canon = _canonical_label_tokens(carto, ",".join(requested_tags))

    # 7) resolve_beacon_comment (ordered contract; parser-normalized form).
    # 2R4E1P: a fill-mode conflict is KEPT, never a plan failure -- the
    # resolver returns kept_existing_conflict (resolved = the kept comment)
    # with a warning; the labels are still ensured below and the warning
    # rides the plan to the batch row.
    resolution = resolve_beacon_comment(
        intent=intent,
        note_comment=note_comment,
        disk_comment=disk_comment,
        beacon_exists_on_disk=selected is not None,
    )

    mutation = carto.plan_beacon_node_mutation(snapshot, selection, {
        "kind": selection_target["operation"], "tags": requested_canon,
        "resolved_comment": resolution.resolved, "comment_resolution": resolution.to_dict(),
        "comment_intent": intent, "name": cached_name})
    from ..beacon_batch import project_snapshot_evidence
    evidence = project_snapshot_evidence(snapshot, language, selection, mutation,
                                         requested_tags=requested_canon)
    if not mutation["success"]:
        return _fail(mutation["error"], mutation["error_kind"], cached_name=cached_name,
                     file_node_id=file_node_id, source_path=source_path, language=language,
                     occurrence=occurrence, candidates=tuple(mutation["candidates"]),
                     diagnostics=tuple(mutation["diagnostics"]), selection_target=selection_target,
                      physical_witness=selection.get("physical_witness"), evidence=evidence)
    intended = mutation["intended_slice_labels"]
    planned_operation = mutation["planned_operation"]
    noop_reason = mutation["noop_reason"]
    target_key = mutation["target_key"]

    if planned_operation == "noop":
        return BeaconWritePlan(
            success=True,
            planned_operation="noop",
            node_id=str(node_id),
            target_key=target_key,
            cached_name=cached_name,
            intended_name=cached_name,
            write_intent=BeaconWriteIntent(comment=intent, source="lightning_rod"),
            occurrence=occurrence,
            file_node_id=file_node_id,
            source_path=source_path,
            language=language,
            beacon_id=disk_beacon_id,
            note_comment=note_comment,
            disk_comment=disk_comment,
            comment_outcome=resolution.outcome,
            resolved_comment=mutation["resolved_comment"],
            intended_slice_labels=tuple(intended),
            source_sha256=None,
            noop_reason=noop_reason,
            comment_warning=resolution.warning,
            selection_target=selection_target,
            physical_witness=mutation["physical_witness"],
            candidates=tuple(mutation["candidates"]),
            diagnostics=tuple(mutation["diagnostics"]),
            evidence=evidence,
        )

    # CREATE-PATH ID CHOICE: Markdown create REUSES the note-carried id when
    # present and non-colliding (id stability across the next F12+1);
    # Python/JS/Vue mint a FRESH auto id at commit time.
    if planned_operation == "create":
        plan_beacon_id = (
            note_beacon_id_value
            if (language == "markdown" and note_beacon_id_value
                and not any(b["fields"].get("id") == note_beacon_id_value for b in structures["records"]))
            else None
        )
    else:
        plan_beacon_id = disk_beacon_id

    # 10) intended_name -- the writer OPERAND (decoration-clean base name +
    # intended_labels rendered as trailing tags; drives slice_labels ONLY,
    # never role, on the plan branch).
    base_name, _existing_tags = carto.split_name_and_tags(cached_name)
    intended_name = base_name
    if intended:
        intended_name = f"{base_name} {' '.join('#' + t for t in intended)}".strip()

    # 9) Fingerprint the observation parsed in step 4, never a later version.
    source_sha256 = snapshot.sha256 if include_fingerprint else None

    return BeaconWritePlan(
        success=True,
        planned_operation=planned_operation,
        node_id=str(node_id),
        target_key=target_key,
        cached_name=cached_name,
        intended_name=intended_name,
        write_intent=BeaconWriteIntent(comment=intent, source="lightning_rod"),
        occurrence=occurrence,
        file_node_id=file_node_id,
        source_path=source_path,
        language=language,
        beacon_id=plan_beacon_id,
        note_comment=note_comment,
        disk_comment=disk_comment,
        comment_outcome=resolution.outcome,
        resolved_comment=mutation["resolved_comment"],
        intended_slice_labels=tuple(intended),
        source_sha256=source_sha256,
        comment_warning=resolution.warning,
        selection_target=selection_target,
        physical_witness=mutation["physical_witness"],
        candidates=tuple(mutation["candidates"]),
        diagnostics=tuple(mutation["diagnostics"]),
        evidence=evidence,
    )


def _compute_beacon_write_plan_over_nodes(
    nodes: list,
    node_id: str,
    operation: Any,
    mode: str,
    *,
    include_fingerprint: bool,
) -> "BeaconWritePlan":
    """Build the ``{uuid: node}`` map and run the pure plan computation.

    The synchronous body of the preflight/plan client seams, kept in one place
    so both run it in a worker thread (NBBW) instead of on the event loop.
    """
    nodes_by_id = {str(n.get("id")): n for n in (nodes or []) if n.get("id")}
    return _compute_beacon_write_plan(
        nodes_by_id, node_id, operation, mode, include_fingerprint=include_fingerprint
    )


# @beacon[
#   id=beacon-writeback@_commit_beacon_write_plan_over_nodes,
#   role=_commit_beacon_write_plan_over_nodes(nodes, plan, note),
#   slice_labels=beacon-writeback,
#   kind=ast,
#   comment=The synchronous body of commit_beacon_write_plan, run in a worker thread (NBBW): re-resolves the target from the cache, returns plan_mismatch with ZERO write on any path/FILE-node divergence, then calls the language helper with the plan (at most ONE atomic replacement behind the plan's sha256 CAS). No cache patching, no auto-refresh.,
# ]
def _commit_beacon_write_plan_over_nodes(nodes: list, plan: "BeaconWritePlan", note: str) -> dict:
    """The synchronous body of ``commit_beacon_write_plan`` (runs in a worker thread).

    Re-resolves the target, verifies it against the plan (divergence =
    ``plan_mismatch``, ZERO write) and calls the language helper with the plan,
    which performs at most ONE atomic replacement behind the plan's CAS.
    """
    nodes_by_id = {str(n.get("id")): n for n in (nodes or []) if n.get("id")}
    target = _resolve_beacon_target_from_cache(nodes_by_id, plan.node_id)
    if not target.get("success"):
        return {
            "success": False,
            "operation": None,
            "error": target.get("error"),
            "error_kind": target.get("error_kind") or "plan_mismatch",
            "node_id": plan.node_id,
            "disk_changed": False,
        }

    planned_path = str(plan.source_path or "")
    resolved_path = str(target.get("source_path") or "")
    if planned_path and os.path.normcase(os.path.realpath(planned_path)) != os.path.normcase(
        os.path.realpath(resolved_path)
    ):
        return {
            "success": False,
            "operation": None,
            "error": (
                f"plan_mismatch: planned source path {planned_path!r} "
                f"diverged from resolved {resolved_path!r}"
            ),
            "error_kind": "plan_mismatch",
            "node_id": plan.node_id,
            "disk_changed": False,
        }
    if plan.file_node_id and str(plan.file_node_id) != str(target.get("file_node_id")):
        return {
            "success": False,
            "operation": None,
            "error": "plan_mismatch: enclosing FILE node diverged since plan",
            "error_kind": "plan_mismatch",
            "node_id": plan.node_id,
            "disk_changed": False,
        }

    language = target.get("language")
    helper = (
        getattr(target["cartographer"], _BEACON_LANGUAGE_HELPER_NAME[language], None)
        if language
        else None
    )
    if helper is None:
        return {
            "success": False,
            "operation": None,
            "error": f"unsupported extension {target.get('ext')!r} for beacon mutation",
            "error_kind": "operation_not_supported_for_target",
            "source_path": resolved_path,
            "node_id": plan.node_id,
            "disk_changed": False,
        }

    log_event(
        f"commit_beacon_write_plan dispatch (node_id={plan.node_id}, "
        f"source_path={resolved_path!r}, lang={language}, "
        f"planned_op={plan.planned_operation}, beacon_id={plan.beacon_id!r})",
        "BEACON",
    )

    try:
        if language == "markdown":
            result = helper(
                resolved_path,
                plan.intended_name,
                note,
                occurrence=plan.occurrence,
                write_intent=plan.write_intent,
                write_plan=plan,
            )
        else:
            result = helper(
                resolved_path,
                plan.intended_name,
                note,
                write_intent=plan.write_intent,
                write_plan=plan,
            )
    except Exception as e:  # noqa: BLE001
        return {
            "success": False,
            "operation": None,
            "error": f"commit helper failed for {resolved_path!r}: {e}",
            "error_kind": "commit_helper_error",
            "source_path": resolved_path,
            "node_id": plan.node_id,
            "disk_changed": False,
        }

    if not isinstance(result, dict):
        result = {"raw_result": result}

    operation = result.get("operation")
    if result.get("error"):
        result["success"] = False
    else:
        result.setdefault("success", True)
    result.setdefault("node_id", plan.node_id)
    result.setdefault("source_path", resolved_path)
    result["file_node_id"] = target.get("file_node_id")
    result["language"] = language
    # invariant 9 / SINGLE-WRITE-TARGET: exactly one atomic replacement
    # happened, or NOTHING was mutated anywhere.
    result["disk_changed"] = bool(
        result.get("success")
        and operation in {"created_beacon", "updated_beacon", "deleted_beacon"}
    )
    # NO cache patching, NO auto-refresh (the user's standing F12+1 pass
    # owns Workflowy/cache synchronization).
    result["auto_refresh"] = {"success": False, "reason": "mutation_path_no_refresh"}
    return result


# @beacon[
#   id=beacon-writeback@_await_thread_to_completion,
#   role=async _await_thread_to_completion(func, *args),
#   slice_labels=beacon-writeback,carto-governance,
#   kind=ast,
#   comment=Run blocking disk work in a worker thread WITHOUT ever abandoning it: a cancellation is held (asyncio.wait never cancels the task) until the thread has finished, then re-raised. Used by commit_beacon_write_plan so a cancelled beacon batch releases its Q3 lease strictly after the in-flight write (NBBW).,
# ]
async def _await_thread_to_completion(func: Callable[..., Any], /, *args: Any) -> Any:
    """Run blocking work in a worker thread and never abandon it (NBBW).

    ``asyncio.to_thread`` alone would let a cancelled caller move on while the
    thread keeps writing. Here a cancellation is held until the thread has
    finished, then re-raised, so everything the caller does after us (e.g. a
    Q3 lease release in its ``finally``) happens strictly after the work.
    """
    # Exactly what asyncio.to_thread does (default executor + copied context),
    # but kept as a plain executor Future so it can be awaited without a Task.
    loop = asyncio.get_running_loop()
    ctx = contextvars.copy_context()
    fut = loop.run_in_executor(None, functools.partial(ctx.run, func, *args))
    cancelled = False
    while not fut.done():
        try:
            # asyncio.wait never cancels the future and never raises its error.
            await asyncio.wait({fut})
        except asyncio.CancelledError:
            cancelled = True
    if cancelled:
        raise asyncio.CancelledError()
    return fut.result()


# @beacon[
#   id=auto-beacon@WorkFlowyClientNexus.read_text_snippet_by_symbol._is_hide_cartographer_node-9s4h,
#   role=_symres_is_hide_cartographer_node,
#   slice_labels=ra-snippet-range,ra-read-text-snippet,
#   kind=ast,
# ]
def _symres_is_hide_cartographer_node(node: dict[str, Any]) -> bool:
    raw_name = str(node.get("name") or "")
    name = raw_name.strip()
    if not name:
        return False
    tokens = name.split()
    # Drop trailing #tags.
    while tokens and str(tokens[-1]).startswith("#"):
        tokens.pop()
    if not tokens:
        return False
    core = " ".join(tokens).strip().lower()
    return core == "hide cartographer"


def _symres_canonical_path(path: str) -> str:
    return os.path.normcase(os.path.normpath(path))


def _symres_normalize_note_path(p: str) -> str:
    # normalize to forward slashes for comparison
    p2 = (p or "").strip().replace("\\", "/")
    while p2.startswith("./"):
        p2 = p2[2:]
    return p2


# @beacon[
#   id=auto-beacon@WorkFlowyClientNexus.read_text_snippet_by_symbol._extract_beacon_fields-gb8d,
#   role=_symres_extract_beacon_fields,
#   slice_labels=ra-reconcile,ra-read-text-snippet,
#   kind=ast,
# ]
def _symres_extract_beacon_fields(note_str: str) -> tuple[str | None, str | None]:
    beacon_id_val: str | None = None
    role_val: str | None = None
    if "BEACON (" not in note_str and "@beacon[" not in note_str:
        return None, None
    for line in note_str.splitlines():
        stripped = line.strip()
        if stripped.startswith("id:"):
            beacon_id_val = stripped.split(":", 1)[1].strip()
        elif stripped.startswith("role:"):
            role_val = stripped.split(":", 1)[1].strip()
    return beacon_id_val or None, role_val or None


# @beacon[
#   id=auto-beacon@WorkFlowyClientNexus.read_text_snippet_by_symbol._extract_ast_qualname-0hpl,
#   role=_symres_extract_ast_qualname,
#   slice_labels=ra-reconcile,ra-read-text-snippet,
#   kind=ast,
# ]
def _symres_extract_ast_qualname(note_str: str) -> str | None:
    for line in note_str.splitlines():
        stripped = line.strip()
        if stripped.startswith("AST_QUALNAME:"):
            return stripped.split(":", 1)[1].strip() or None
    return None


# @beacon[
#   id=auto-beacon@WorkFlowyClientNexus.read_text_snippet_by_symbol._normalize_node_name-rkap,
#   role=_symres_normalize_node_name,
#   slice_labels=ra-reconcile,ra-read-text-snippet,
#   kind=ast,
# ]
def _symres_normalize_node_name(raw_name: str | None) -> str:
    if not raw_name:
        return ""
    name = str(raw_name)
    # Strip leading decoration/emoji until alnum/underscore/dollar.
    i = 0
    while i < len(name) and not (name[i].isalnum() or name[i] in {"_", "$"}):
        i += 1
    name = name[i:].strip()
    if not name:
        return ""
    tokens = name.split()
    # Drop trailing #tags.
    while tokens and str(tokens[-1]).startswith("#"):
        tokens.pop()
    if not tokens:
        return ""
    # Drop structural prefixes like "ƒ", "class", "function", "method".
    #
    # NOTE: Vue-mapped nodes commonly appear as: "ƒ function updateScrollState()"
    # so we need to drop *multiple* consecutive structural tokens.
    while tokens and tokens[0] in {
        "ƒ",
        "class",
        "function",
        "method",
        "def",
        "async",
        "export",
        "default",
    }:
        tokens = tokens[1:]
    if not tokens:
        return ""
    core = " ".join(tokens)
    # Strip parameters after '('.
    paren = core.find("(")
    if paren != -1:
        core = core[:paren].strip()
    return core


# @beacon[
#   id=snippet-symbol@read_text_snippet_by_symbol._normalize_markdown_heading_name,
#   slice_labels=ra-read-text-snippet,nexus-md-header-path,ra-snippet-range,nexus-path-resolution-logic,
#   kind=ast,
#   comment=Markdown-only symbol normalization: trim leading decoration and trailing tags without source-code fuzzy splitting,
# ]
def _symres_normalize_markdown_heading_name(raw_name: str | None) -> str:
    """Normalize a Markdown heading/symbol without source-code fuzziness.

    Markdown headings are prose, not identifiers.  Keep the cleanup to the
    two user-facing conveniences that are safe for prose headings:
    leading decoration/emoji removal and trailing #tag removal.  In
    particular, do NOT take the last whitespace-delimited word and do NOT
    strip parenthesized text; both are too broad for Markdown headings and
    can create enormous ambiguity reports across the whole vault.
    """
    if not raw_name:
        return ""
    name = str(raw_name)
    i = 0
    while i < len(name) and not (name[i].isalnum() or name[i] in {"_", "$"}):
        i += 1
    name = name[i:].strip()
    if not name:
        return ""
    tokens = name.split()
    while tokens and str(tokens[-1]).startswith("#"):
        tokens.pop()
    return " ".join(tokens).strip()


# @beacon[
#   id=snippet-symbol@read_text_snippet_by_symbol._is_markdownish_path,
#   slice_labels=ra-read-text-snippet,nexus-md-header-path,ra-snippet-range,nexus-path-resolution-logic,
#   kind=ast,
#   comment=Markdown-only symbol resolution guard: detect Markdown-like file paths,
# ]
def _symres_is_markdownish_path(path: str | None) -> bool:
    p = _symres_normalize_note_path(path or "").lower()
    return p.endswith((".md", ".markdown", ".mdx"))


# @beacon[
#   id=snippet-symbol@read_text_snippet_by_symbol._node_looks_markdown,
#   slice_labels=ra-read-text-snippet,nexus-md-header-path,ra-snippet-range,nexus-path-resolution-logic,
#   kind=ast,
#   comment=Markdown-only symbol resolution guard: detect Markdown nodes even when scanning from a Root folder,
# ]
def _symres_node_looks_markdown(note_str: str, owner_path: str | None) -> bool:
    if _symres_is_markdownish_path(owner_path):
        return True
    if "MD_PATH:" in note_str:
        return True
    hdr = _extract_path_header_from_note(note_str)
    return bool(hdr and hdr[0] == "Path" and _symres_is_markdownish_path(hdr[1]))


# @beacon[
#   id=handle-resolution@_SymbolResolutionIndex,
#   role=class _SymbolResolutionIndex,
#   slice_labels=handle-resolution,ra-read-text-snippet,ra-workflowy-cache,
#   kind=ast,
#   comment=ONE per cache generation (NBBW follow-up): everything the symbol resolver used to rebuild on every call -- the {uuid: node} map, HIDE CARTOGRAPHER filtering, the FILE nodes with their resolved absolute paths, the children index, every FILE root's subtree walk in the original order (visits), per-node pre-extracted fields (beacon id/role, AST_QUALNAME and its short name, code and Markdown normalized names, Path header, basename/stem, Markdown-ness) and one exact-key map (key -> node ids) that is a superset of every exact match. Built from the immutable nodes list of the pinned CacheView; keyed on that list's identity (every refresh, journal adoption and local COW publication makes a new list). Pure, read-only after build.,
# ]
class _SymbolResolutionIndex:
    """Precomputed symbol-resolution state for ONE immutable nodes list."""

    def __init__(self, all_nodes: list) -> None:
        self.nodes_ref = all_nodes
        self.nodes_by_id: dict[str, dict[str, Any]] = {
            str(n.get("id")): n for n in all_nodes if n.get("id")
        }
        nodes_by_id = self.nodes_by_id
        # (file_node, path_header, abs_path) in the original scan order.
        self.file_nodes: list[tuple[dict[str, Any], str, str | None]] = []
        # Per FILE root position: owner_path_for_record and its Markdown-ness.
        self.root_owner: list[str] = []
        self.root_owner_md: list[bool] = []
        # nid -> [(global_visit_position, root_position), ...] in scan order.
        self.node_visits: dict[str, list[tuple[int, int]]] = {}
        # Every visit in the original full-scan order: (nid, root_position).
        self.all_visits: list[tuple[str, int]] = []
        # nid -> pre-extracted fields tuple (see _fields_for).
        self.fields: dict[str, tuple] = {}
        # exact key -> node ids whose beacon id/role, AST_QUALNAME, short AST
        # name, code/Markdown normalized name, or Path basename/stem equals it.
        self.keys: dict[str, set[str]] = {}
        if not nodes_by_id:
            return

        # HIDE CARTOGRAPHER sentinels (unchanged semantics).
        parent_by_id: dict[str, str] = {}
        for n in all_nodes:
            nid = n.get("id")
            pid = n.get("parent_id") or n.get("parentId")
            if nid and pid:
                parent_by_id[str(nid)] = str(pid)
        hide_ids: set[str] = set()
        for n in nodes_by_id.values():
            if _symres_is_hide_cartographer_node(n):
                nid = n.get("id")
                if nid:
                    hide_ids.add(str(nid))

        def _is_under_hidden_subtree(node_id: str) -> bool:
            cur = node_id
            visited: set[str] = set()
            while cur and cur not in visited:
                if cur in hide_ids:
                    return True
                visited.add(cur)
                cur = parent_by_id.get(cur)
            return False

        # FILE nodes via Path:/Root: headers, resolved to absolute paths once
        # per generation (portability PR1.1 semantics unchanged).
        for n in nodes_by_id.values():
            n_note = n.get("note") or n.get("no") or ""
            path_header = parse_path_or_root_from_note(str(n_note))
            if not path_header:
                continue
            nid = n.get("id")
            sid = str(nid) if nid else None
            if sid and _is_under_hidden_subtree(sid):
                continue
            abs_path: str | None = None
            if sid:
                try:
                    resolved = resolve_cartographer_path_from_node(
                        node_id=sid,
                        nodes_by_id=nodes_by_id,
                    )
                    abs_path = str(resolved.get("abs_path") or "") or None
                except Exception:
                    abs_path = None
            self.file_nodes.append((n, path_header, abs_path))

        children_by_parent: dict[str, list[dict[str, Any]]] = {}
        for n in all_nodes:
            pid = n.get("parent_id") or n.get("parentId")
            if pid:
                children_by_parent.setdefault(str(pid), []).append(n)

        pos = 0
        for root_pos, (file_node, owner_path, owner_abs_path) in enumerate(self.file_nodes):
            owner_path_for_record = owner_abs_path or owner_path
            self.root_owner.append(owner_path_for_record)
            self.root_owner_md.append(_symres_is_markdownish_path(owner_path_for_record))
            root_id = str(file_node.get("id")) if file_node.get("id") else None
            if not root_id:
                continue
            # The original _iter_subtree walk, verbatim (stack DFS, per-root visited).
            stack = [root_id]
            visited: set[str] = set()
            while stack:
                nid = stack.pop()
                if nid in visited:
                    continue
                visited.add(nid)
                node = nodes_by_id.get(nid)
                if not node:
                    continue
                self.all_visits.append((nid, root_pos))
                self.node_visits.setdefault(nid, []).append((pos, root_pos))
                pos += 1
                if nid not in self.fields:
                    self.fields[nid] = self._fields_for(node)
                for child in children_by_parent.get(nid, []) or []:
                    cid = child.get("id")
                    if cid:
                        stack.append(str(cid))

        keys = self.keys
        for nid, f in self.fields.items():
            for k in f[_F_KEYS]:
                if k:
                    keys.setdefault(k, set()).add(nid)

    @staticmethod
    def _fields_for(node: dict[str, Any]) -> tuple:
        note_str = str(node.get("note") or node.get("no") or "")
        bid, role = _symres_extract_beacon_fields(note_str)
        ast_q = _symres_extract_ast_qualname(note_str)
        short = _symres_short_ast_name(ast_q) if ast_q else None
        norm_code = _symres_normalize_node_name(node.get("name"))
        norm_md = _symres_normalize_markdown_heading_name(node.get("name"))
        hdr = _extract_path_header_from_note(note_str)
        hdr_base = hdr_stem = None
        if hdr and hdr[0] == "Path":
            hdr_base = os.path.basename(_symres_normalize_note_path(hdr[1]))
            hdr_stem = Path(hdr_base).stem
        node_md = _symres_node_looks_markdown(note_str, None)
        exact_keys = (bid, role, ast_q, short, norm_code, norm_md, hdr_base, hdr_stem)
        return (note_str, bid, role, ast_q, short, norm_code, norm_md, hdr, hdr_base, hdr_stem, node_md, exact_keys)


# Field positions in _SymbolResolutionIndex.fields tuples.
(
    _F_NOTE, _F_BID, _F_ROLE, _F_AST, _F_SHORT, _F_NORM_CODE, _F_NORM_MD,
    _F_HDR, _F_HDR_BASE, _F_HDR_STEM, _F_NODE_MD, _F_KEYS,
) = range(12)


def _symres_short_ast_name(q: str) -> str:
    # Python: WorkFlowyClientNexus.read_text_snippet_by_symbol
    # Vue:    vue:script0:updateScrollState
    # JS/TS:  may include either '.' or ':' depending on the mapper
    s = (q or "").strip()
    if ":" in s:
        s = s.rsplit(":", 1)[-1]
    if "." in s:
        s = s.rsplit(".", 1)[-1]
    return s


_SYMBOL_INDEX_LOCK = threading.Lock()
_SYMBOL_INDEX_SLOT: "list[_SymbolResolutionIndex]" = []


# @beacon[
#   id=handle-resolution@_live_nodes_for_symbol_legs,
#   role=_live_nodes_for_symbol_legs(client),
#   slice_labels=handle-resolution,ra-read-text-snippet,ra-workflowy-cache,
#   kind=ast,
#   comment=THE ONE node list the symbol legs read (Archive Reads U1, §4.8): when the current snapshot's archive context carries an overlay, the LIVE view's nodes list -- the symbol legs never see an overlay record and the per-generation symbol index stays keyed on the live list (same identity as a non-augmented operation's, so no index thrash); otherwise today's export_nodes_impl list, byte-identically. read_text_snippet_by_symbol and beacon_get_code_snippet obtain all_nodes ONLY through it. A UUID or AP item of render_symbols/render_nodes that resolves to an archive record renders from the record and is never passed to a disk or snippet tier.,
# ]
async def _live_nodes_for_symbol_legs(client: Any) -> list:
    """The node list for every symbol leg — always the LIVE list (Axiom 12).

    Inside an archive-augmented operation the pinned map carries overlay
    records; feeding them to the symbol legs would index archived mapped
    nodes AND evict the live per-generation symbol index.  This ONE
    accessor hands back the live view's own nodes list in that case, and
    today's ``export_nodes_impl`` list otherwise (byte-identical; the same
    loud CacheViewError outside a boundary).
    """
    from ..coherence.operation_cache import current_operation_cache

    snapshot = current_operation_cache(required=False)
    context = getattr(snapshot, "archive", None) if snapshot is not None else None
    overlay = getattr(context, "overlay", None) if context is not None else None
    if overlay is not None:
        return overlay.live_view.nodes_export["nodes"]
    raw = await export_nodes_impl(
        client, node_id=None, use_cache=True, force_refresh=False
    )
    return raw.get("nodes") or []


# @beacon[
#   id=handle-resolution@_symbol_resolution_index_for,
#   role=_symbol_resolution_index_for(all_nodes),
#   slice_labels=handle-resolution,ra-read-text-snippet,ra-workflowy-cache,
#   kind=ast,
#   comment=The ONE accessor for the per-generation symbol index: a single slot keyed on the identity of the pinned CacheView's immutable nodes list (strong reference held, so identity is sound); a new generation rebuilds and replaces it under one lock. Called from worker threads only (the build walks the whole cache). No TTL, no knob. Always the live list (archives never reach it) -- every symbol leg obtains all_nodes through _live_nodes_for_symbol_legs, so the slot never holds an augmented list.,
# ]
def _symbol_resolution_index_for(all_nodes: list) -> _SymbolResolutionIndex:
    with _SYMBOL_INDEX_LOCK:
        if _SYMBOL_INDEX_SLOT and _SYMBOL_INDEX_SLOT[0].nodes_ref is all_nodes:
            return _SYMBOL_INDEX_SLOT[0]
        index = _SymbolResolutionIndex(all_nodes)
        _SYMBOL_INDEX_SLOT[:] = [index]
        return index


# @beacon[
#   id=handle-resolution@_resolve_symbol_candidates_sync,
#   role=_resolve_symbol_candidates_sync(all_nodes, file_path, symbol, symbol_kind, *, return_candidates_only, suppress_tags, scope_root_ids),
#   slice_labels=handle-resolution,ra-read-text-snippet,ra-snippet-range,nexus-path-resolution-logic,
#   kind=ast,
#   comment=THE symbol-resolution pipeline behind read_text_snippet_by_symbol / read_uuid_from_symbol (beacon.resolve, beacon.snippet by name, the Q3 batch Phase B, render_symbols), synchronous so callers run it in a worker thread. Same steps and results as before the index (file_path narrowing, beacon/ast/name exact scan, dotted-tail, contains and cross-kind fallbacks, #wfy-suppress filter before 0/1/N, descriptors, errors); the per-visit match block runs only over the visits of nodes whose exact keys can match a symbol variant (a superset of every exact hit), and over every visit, exactly as before, only when the requested kinds find no exact hit. scope_root_ids ([ap:WB323O] root_handles) drops candidates outside every root AFTER suppression and BEFORE the 0/1/N decision -- the same descendant-of-any-root gate render_symbols applies; a symbol matched only outside the scope raises a not-found naming the scope (candidates-only mode reports scope_filtered_count instead of raising). Returns the candidates-only dict, or ('resolved', target_id, nodes_by_id, requested_symbol_kind, node_to_file_path) for the snippet path; raises NetworkError on none / many.,
# ]
def _resolve_symbol_candidates_sync(
    all_nodes: list,
    file_path: str | None,
    symbol: str,
    symbol_kind: str,
    *,
    return_candidates_only: bool,
    suppress_tags: "list[str] | None",
    scope_root_ids: "list[str] | None" = None,
) -> Any:
    index = _symbol_resolution_index_for(all_nodes)
    nodes_by_id = index.nodes_by_id
    if not nodes_by_id:
        raise NetworkError(
            "read_text_snippet_by_symbol: /nodes-export snapshot is empty; cannot resolve symbol",
        )
    file_nodes = index.file_nodes
    if not file_nodes:
        raise NetworkError(
            "read_text_snippet_by_symbol: no Cartographer-mapped FILE nodes with Path:/Root: found",
        )
    # 3) Restrict FILE set by file_path when provided.
    #
    # - If file_path is absolute, match against resolved abs_path.
    # - If file_path is relative with separators, match against the note header.
    # - If file_path is a basename, match by basename of the note header.
    search_roots: list[tuple[dict[str, Any], str, str | None]]
    if file_path:
        fp = file_path.strip()
        if not fp:
            search_roots = file_nodes
        else:
            is_abs = _looks_absolute_path(fp)
            fp_norm = _symres_normalize_note_path(fp)

            matches: list[tuple[dict[str, Any], str, str | None]] = []
            if is_abs:
                target_norm = _symres_canonical_path(fp)
                matches = [
                    (n, p, ap) for (n, p, ap) in file_nodes
                    if ap and _symres_canonical_path(ap) == target_norm
                ]
            else:
                if "/" in fp_norm or "\\" in fp:
                    # Relative path filter.
                    #
                    # Cartographer FILE nodes often store only a basename in their
                    # note header ("Path: InterviewComparisonGrid.vue") even when
                    # the caller provides a repo-relative path
                    # ("frontend/src/components/InterviewComparisonGrid.vue").
                    #
                    # Therefore we match against either:
                    #   1) the literal Path:/Root: header, OR
                    #   2) the resolved on-disk absolute path (suffix match).
                    matches = [
                        (n, p, ap)
                        for (n, p, ap) in file_nodes
                        if _symres_normalize_note_path(p) == fp_norm
                        or (ap and _symres_normalize_note_path(ap).endswith(fp_norm))
                    ]
                else:
                    # Basename filter.
                    #
                    # Accept either an exact basename ("SampleTile.vue") or an
                    # extensionless stem ("SampleTile") when unambiguous.
                    matches = [
                        (n, p, ap)
                        for (n, p, ap) in file_nodes
                        if os.path.basename(p) == fp
                        or Path(os.path.basename(p)).stem == fp
                        or (ap and Path(os.path.basename(ap)).stem == fp)
                    ]

            if not matches:
                raise NetworkError(
                    "read_text_snippet_by_symbol: no FILE node with Path:/Root: matching "
                    f"{file_path!r} was found",
                )

            # Prefer matches that correspond to real files on disk.
            existing_matches = [
                (n, p, ap)
                for (n, p, ap) in matches
                if ap and os.path.isfile(ap)
            ]
            if existing_matches:
                matches = existing_matches

            paths = sorted({(ap or p) for _, p, ap in matches})
            if len(paths) > 1:
                raise NetworkError(
                    "read_text_snippet_by_symbol: ambiguous file_path; matches: "
                    + ", ".join(repr(p) for p in paths),
                )
            search_roots = matches

    else:
        search_roots = file_nodes

    # Build symbol variants for robust matching.
    #
    # Example:
    #   symbol="class WorkFlowyNode" should match AST_QUALNAME="WorkFlowyNode".
    symbol_norm = _symres_normalize_node_name(symbol)
    symbol_tail = symbol.split()[-1].strip() if symbol.split() else ""
    if symbol_tail:
        # Strip parameters and common trailing punctuation.
        if "(" in symbol_tail:
            symbol_tail = symbol_tail.split("(", 1)[0].strip()
        symbol_tail = symbol_tail.strip(":,;{}[]")

    symbol_variants: list[str] = []
    for v in (symbol, symbol_norm, symbol_tail):
        vv = (v or "").strip()
        if vv and vv not in symbol_variants:
            symbol_variants.append(vv)

    # Markdown-specific variants intentionally exclude symbol_tail.  A prose
    # heading like "Project Training Migration - Final Vetting" must not turn
    # into a vault-wide substring/exact search for just "Vetting".
    markdown_symbol_norm = _symres_normalize_markdown_heading_name(symbol)
    markdown_symbol_variants: list[str] = []
    for v in (symbol, markdown_symbol_norm):
        vv = (v or "").strip()
        if vv and vv not in markdown_symbol_variants:
            markdown_symbol_variants.append(vv)

    # Buckets for matches by strategy.
    node_to_file_path: dict[str, str] = {}
    beacon_hits: set[str] = set()
    ast_hits: set[str] = set()
    name_hits: set[str] = set()

    # Contains-based fallback buckets (only consulted if no exact matches).
    # These help when the caller passes a descriptive symbol like:
    #   "class WorkFlowyNode"
    # or includes emoji/tag noise.
    contains_beacon_hits: set[str] = set()
    contains_ast_hits: set[str] = set()
    contains_name_hits: set[str] = set()

    # Needles for substring search. We keep this conservative:
    # - Use symbol_variants (original + normalized + tail)
    # - Ignore very short tokens (<3 chars)
    contains_needles = [v for v in symbol_variants if len(v) >= 3]
    contains_needles_lc = [v.lower() for v in contains_needles]

    # @beacon[
    #   id=auto-beacon@WorkFlowyClientNexus.read_text_snippet_by_symbol._record_hit-oous,
    #   role=WorkFlowyClientNexus.read_text_snippet_by_symbol._record_hit,
    #   slice_labels=ra-reconcile,ra-read-text-snippet,
    #   kind=ast,
    # ]
    def _record_hit(node: dict[str, Any], owner_path: str, bucket: str) -> None:
        nid = node.get("id")
        if not nid:
            return
        s_nid = str(nid)
        node_to_file_path.setdefault(s_nid, owner_path)
        if bucket == "beacon":
            beacon_hits.add(s_nid)
        elif bucket == "ast":
            ast_hits.add(s_nid)
        elif bucket == "name":
            name_hits.add(s_nid)

    # @beacon[
    #   id=snippet-symbol@read_text_snippet_by_symbol._record_contains_hit,
    #   role=read_text_snippet_by_symbol._record_contains_hit,
    #   slice_labels=ra-reconcile,ra-read-text-snippet,ra-snippet-range,
    #   kind=ast,
    #   comment=Helper: record a candidate match based on contains-substring fallback,
    # ]
    def _record_contains_hit(node: dict[str, Any], owner_path: str, bucket: str) -> None:
        nid = node.get("id")
        if not nid:
            return
        s_nid = str(nid)
        node_to_file_path.setdefault(s_nid, owner_path)
        if bucket == "beacon":
            contains_beacon_hits.add(s_nid)
        elif bucket == "ast":
            contains_ast_hits.add(s_nid)
        elif bucket == "name":
            contains_name_hits.add(s_nid)

    # Determine which strategies are enabled.
    #
    # Accept a few human-friendly aliases so callers can use values like
    # "function" (common mental model) instead of our internal "name".
    requested_symbol_kind_raw = (symbol_kind or "auto").strip().lower()
    symbol_kind_aliases: dict[str, str] = {
        "auto": "auto",
        "beacon": "beacon",
        "ast": "ast",
        "name": "name",
        # Friendly aliases
        "function": "name",
        "method": "name",
        "class": "name",
        "identifier": "name",
        "qualname": "ast",
    }
    requested_symbol_kind = symbol_kind_aliases.get(
        requested_symbol_kind_raw,
        requested_symbol_kind_raw,
    )
    if requested_symbol_kind not in {"auto", "beacon", "ast", "name"}:
        # Soft fallback for unknown kinds: treat as 'auto' rather than
        # failing hard. This keeps callers resilient to arbitrary labels
        # while preserving explicit behavior for known kinds.
        requested_symbol_kind = "auto"

    use_beacon = requested_symbol_kind in {"auto", "beacon"}
    use_ast = requested_symbol_kind in {"auto", "ast"}
    use_name = requested_symbol_kind in {"auto", "name"}

    # Always collect all strategy buckets during the scan so we can
    # transparently fallback to cross-kind resolution if the requested
    # kind yields no match.
    collect_beacon = True
    collect_ast = True
    collect_name = True

    # 4-5) Scan (INDEXED). The per-visit block below is the original scan
    # body over pre-extracted fields; it runs, in the original visit order,
    # over (a) only the visits of nodes whose exact keys can equal a symbol
    # variant (every exact hit is such a node), or (b) every visit, when the
    # requested kinds find no exact hit and the contains / cross-kind
    # fallbacks need the complete buckets.
    root_pos_by_node = {id(n): i for i, (n, _p, _ap) in enumerate(file_nodes)}
    allowed_roots = {root_pos_by_node[id(n)] for (n, _p, _ap) in search_roots}
    fields_by_id = index.fields
    root_owner = index.root_owner
    root_owner_md = index.root_owner_md

    def _scan_visit(nid: str, root_pos: int) -> None:
        node = nodes_by_id[nid]
        f = fields_by_id[nid]
        note_str = f[_F_NOTE]
        owner_path_for_record = root_owner[root_pos]
        node_is_markdown = root_owner_md[root_pos] or f[_F_NODE_MD]
        exact_variants = markdown_symbol_variants if node_is_markdown else symbol_variants

        if collect_beacon:
            beacon_id_val, role_val = f[_F_BID], f[_F_ROLE]
            if (beacon_id_val and beacon_id_val in exact_variants) or (
                role_val and role_val in exact_variants
            ):
                _record_hit(node, owner_path_for_record, "beacon")

        if collect_ast:
            ast_q = f[_F_AST]
            if ast_q:
                # Qualified variant ('.' or ':') -> exact equality; otherwise
                # match the final segment of the qualname.
                short = f[_F_SHORT]
                matched = False
                for v in exact_variants:
                    if not v:
                        continue
                    if "." in v or ":" in v:
                        if ast_q == v:
                            matched = True
                            break
                    else:
                        if short == v:
                            matched = True
                            break
                if matched:
                    _record_hit(node, owner_path_for_record, "ast")

        if collect_name:
            norm_name = f[_F_NORM_MD] if node_is_markdown else f[_F_NORM_CODE]
            if norm_name:
                if norm_name in exact_variants:
                    _record_hit(node, owner_path_for_record, "name")
                else:
                    # Convenience: allow resolving FILE nodes by filename/stem.
                    hdr_base = f[_F_HDR_BASE]
                    if hdr_base is not None:
                        if hdr_base in exact_variants or f[_F_HDR_STEM] in exact_variants:
                            _record_hit(node, owner_path_for_record, "name")

        # Contains-based fallbacks (Markdown deliberately excluded).
        if contains_needles_lc and not node_is_markdown:
            raw_name_lc = str(node.get("name") or "").lower()
            note_lc = note_str.lower()

            if collect_beacon:
                beacon_id_val, role_val = f[_F_BID], f[_F_ROLE]
                if beacon_id_val or role_val:
                    bid_lc = (beacon_id_val or "").lower()
                    role_lc = (role_val or "").lower()
                    if any(n in bid_lc for n in contains_needles_lc) or any(
                        n in role_lc for n in contains_needles_lc
                    ):
                        _record_contains_hit(node, owner_path_for_record, "beacon")

            if collect_ast:
                ast_q = f[_F_AST]
                if ast_q:
                    ast_lc = ast_q.lower()
                    if any(n in ast_lc for n in contains_needles_lc):
                        _record_contains_hit(node, owner_path_for_record, "ast")

            if collect_name:
                if any(n in raw_name_lc for n in contains_needles_lc):
                    _record_contains_hit(node, owner_path_for_record, "name")

                hdr = f[_F_HDR]
                if hdr and hdr[0] in {"Path", "Root"}:
                    hdr_lc = str(hdr[1] or "").lower()
                    if any(n in hdr_lc for n in contains_needles_lc):
                        _record_contains_hit(node, owner_path_for_record, "name")

            if any(n in note_lc for n in contains_needles_lc):
                ast_q = f[_F_AST]
                if collect_ast and ast_q:
                    _record_contains_hit(node, owner_path_for_record, "ast")
                elif collect_name:
                    _record_contains_hit(node, owner_path_for_record, "name")

    def _keyed_visits(key_values) -> list[tuple[int, int, str]]:
        cand: set[str] = set()
        for v in key_values:
            if v:
                cand.update(index.keys.get(v, ()))
        visits = [
            (gpos, rpos, nid)
            for nid in cand
            for (gpos, rpos) in index.node_visits.get(nid, ())
            if rpos in allowed_roots
        ]
        visits.sort()
        return visits

    def _main_pass(full: bool) -> None:
        for bucket in (
            beacon_hits, ast_hits, name_hits,
            contains_beacon_hits, contains_ast_hits, contains_name_hits,
        ):
            bucket.clear()
        node_to_file_path.clear()
        if full:
            for nid, rpos in index.all_visits:
                if rpos in allowed_roots:
                    _scan_visit(nid, rpos)
        else:
            main_keys = list(symbol_variants) + list(markdown_symbol_variants)
            if "." in symbol:
                # Nodes the dotted-tail fallback can hit get their main-pass
                # records (contains buckets, first owner) exactly as before.
                main_keys.append(symbol.rsplit(".", 1)[-1].strip())
            for _gpos, rpos, nid in _keyed_visits(main_keys):
                _scan_visit(nid, rpos)

    _main_pass(full=False)

    # 6) Compute union of hits across enabled strategies and enforce uniqueness.
    active_sets: list[set[str]] = []
    if use_beacon:
        active_sets.append(beacon_hits)
    if use_ast:
        active_sets.append(ast_hits)
    if use_name:
        active_sets.append(name_hits)

    union_ids: set[str] = set()
    for s in active_sets:
        union_ids.update(s)

    # Robust fallback: if caller provided a dotted symbol like
    # "WorkFlowyClientNexus._is_cartographer_parse_error_sentinel" but the Cartographer node
    # is module-level ("_is_cartographer_parse_error_sentinel"), retry once using the final
    # segment. This is a common agent failure mode.
    #
    # Safety:
    # - We only do this when the symbol contains a dot.
    # - We do NOT guess further than the last segment.
    # - We still raise ambiguity if multiple matches exist.
    def _dotted_tail_pass() -> None:
        if "." not in symbol:
            return
        tail = symbol.rsplit(".", 1)[-1].strip()
        if not tail or tail == symbol:
            return
        for _gpos, rpos, nid in _keyed_visits([tail]):
            node = nodes_by_id[nid]
            f = fields_by_id[nid]
            owner_path_for_record = root_owner[rpos]
            if root_owner_md[rpos] or f[_F_NODE_MD]:
                # Dotted-tail fallback is identifier-oriented. For Markdown,
                # periods are normal prose punctuation and should not trigger
                # a second broad search on the final sentence fragment.
                continue

            if use_beacon:
                if f[_F_BID] == tail or f[_F_ROLE] == tail:
                    _record_hit(node, owner_path_for_record, "beacon")

            if use_ast:
                ast_q = f[_F_AST]
                if ast_q:
                    if "." in tail or ":" in tail:
                        if ast_q == tail:
                            _record_hit(node, owner_path_for_record, "ast")
                    else:
                        if f[_F_SHORT] == tail:
                            _record_hit(node, owner_path_for_record, "ast")

            if use_name:
                norm_name = f[_F_NORM_CODE]
                if norm_name and norm_name == tail:
                    _record_hit(node, owner_path_for_record, "name")

    if not union_ids:
        _dotted_tail_pass()
        # Recompute union with the updated hit sets.
        union_ids = set()
        for s in active_sets:
            union_ids.update(s)

    if not union_ids:
        # (b) No exact hit for the requested kinds: rebuild EVERY bucket over
        # EVERY visit, exactly as the pre-index full scan, then the dotted
        # tail again, so the contains / cross-kind fallbacks below see the
        # complete buckets.
        _main_pass(full=True)
        _dotted_tail_pass()
        union_ids = set()
        for s in active_sets:
            union_ids.update(s)

    if not union_ids:
        # Last resort: contains-based fallback.
        # This is only used when exact matching fails. It searches for the
        # symbol (or its normalized/tail variants) as a substring in:
        # - node name
        # - AST_QUALNAME line
        # - beacon id/role
        # - Path/Root header
        # - note text (bucketed as AST when AST_QUALNAME exists)
        active_contains: list[set[str]] = []
        if use_beacon:
            active_contains.append(contains_beacon_hits)
        if use_ast:
            active_contains.append(contains_ast_hits)
        if use_name:
            active_contains.append(contains_name_hits)

        for s in active_contains:
            union_ids.update(s)

    if not union_ids and requested_symbol_kind != "auto":
        # Fallback requested by UX: if the requested kind produced no
        # match, try cross-kind resolution before failing.
        fallback_exact = beacon_hits | ast_hits | name_hits
        if fallback_exact:
            union_ids.update(fallback_exact)
        else:
            union_ids.update(
                contains_beacon_hits
                | contains_ast_hits
                | contains_name_hits,
            )

    # GLOBAL SUPPRESSION (Dan's ruling, [ap:7ORCPL]): drop every candidate
    # under a #wfy-suppress'd ancestor AFTER all fallbacks and BEFORE the
    # 0/1/N decision below -- the same post-filter render_symbols applies.
    if suppress_tags and union_ids:
        union_ids = {
            nid
            for nid in union_ids
            if not node_has_suppress_ancestor(nodes_by_id, nid, suppress_tags)
        }

    # ROOT SCOPING (Dan's ask, [ap:WB323O]): when a root_handles scope is
    # given, drop candidates outside EVERY root -- AFTER suppression and
    # BEFORE the 0/1/N decision, the same descendant-of-any-root gate
    # render_symbols applies (scope FILTERS, it never picks an LCA). The
    # filter runs outside the per-generation index (like suppression), so
    # the index stays keyed on the node list only. A symbol matched only
    # outside the scope raises a not-found NAMING the scope (the agent can
    # widen or drop it) instead of a bare "no matching node".
    scope_dropped = 0
    if scope_root_ids and union_ids:
        pre_scope_count = len(union_ids)
        union_ids = {
            nid
            for nid in union_ids
            if is_descendant_of_any_root(nodes_by_id, nid, scope_root_ids)
        }
        scope_dropped = pre_scope_count - len(union_ids)

    # Shared per-candidate descriptor builder. Used by BOTH the ambiguity
    # report (string form) and the candidates-only structured return, so a
    # single match and one row of a multi-match report carry identical
    # fields. Returns a dict; the string form is rendered from it below.
    # @beacon[
    #   id=snippet-symbol@read_text_snippet_by_symbol._build_candidate_descriptor,
    #   slice_labels=ra-read-text-snippet,ra-snippet-range,nexus-path-resolution-logic,
    #   kind=ast,
    #   comment=Shared per-candidate descriptor builder (uuid/name/file_path/ast_qualname/line/via) used by BOTH the ambiguity report and read_uuid_from_symbol's candidates-only return, so a single match and one ambiguity row are byte-identical.
    # ]
    def _build_candidate_descriptor(nid: str) -> dict[str, Any]:
        node = nodes_by_id.get(nid) or {}
        nname = node.get("name") or "(no name)"
        fpath = node_to_file_path.get(nid)
        note_str = str(node.get("note") or node.get("no") or "")
        ast_q = _symres_extract_ast_qualname(note_str)
        line_no = node.get("orig_lineno_start_unused")
        if not isinstance(line_no, int):
            line_no = node.get("line") if isinstance(node.get("line"), int) else None
        if not isinstance(line_no, int) and ast_q:
            # Fallback for Vue/JS synthetic lambda scopes where line metadata
            # may be absent in cached nodes, e.g.:
            #   vue:script0:__lambda_320_3.tintOpts
            m_lambda = re.search(r"__lambda_(\d+)_(\d+)", ast_q)
            if m_lambda:
                try:
                    line_no = int(m_lambda.group(1))
                except Exception:  # noqa: BLE001
                    line_no = None

        buckets: list[str] = []
        if nid in beacon_hits:
            buckets.append("beacon")
        if nid in ast_hits:
            buckets.append("ast")
        if nid in name_hits:
            buckets.append("name")
        if nid in contains_beacon_hits:
            buckets.append("beacon~contains")
        if nid in contains_ast_hits:
            buckets.append("ast~contains")
        if nid in contains_name_hits:
            buckets.append("name~contains")

        return {
            "uuid": nid,
            "name": nname,
            "file_path": fpath,
            "ast_qualname": ast_q,
            "line": line_no if isinstance(line_no, int) else None,
            "via": buckets,
        }

    # @beacon[
    #   id=snippet-symbol@read_text_snippet_by_symbol._render_candidate_line,
    #   slice_labels=ra-read-text-snippet,ra-snippet-range,nexus-path-resolution-logic,
    #   kind=ast,
    #   comment=Render one candidate descriptor as the canonical ambiguity-report line (id=.. line=.. ast=.. name=.. file=.. via=..), preserving the exact pre-refactor string format.
    # ]
    def _render_candidate_line(desc: dict[str, Any]) -> str:
        ast_q = desc.get("ast_qualname") or "(none)"
        fpath = desc.get("file_path") or "(unknown Path)"
        line_no = desc.get("line")
        line_repr = str(line_no) if isinstance(line_no, int) else "?"
        return (
            f"id={desc['uuid']} line={line_repr} ast={ast_q!r} "
            f"name={desc['name']!r} file={fpath!r} via={'+'.join(desc.get('via') or [])}"
        )

    # CANDIDATES-ONLY SHORT-CIRCUIT (read_uuid_from_symbol engine).
    # When the caller only wants resolved UUID(s), return the structured
    # candidate list now -- BEFORE any file read -- covering all three
    # outcomes (0 / 1 / N) without raising. The snippet path below is
    # untouched and only runs when return_candidates_only is False.
    if return_candidates_only:
        max_candidates = 80
        sorted_union_ids = sorted(union_ids)
        descriptors = [
            _build_candidate_descriptor(nid)
            for nid in sorted_union_ids[:max_candidates]
        ]
        result: dict[str, Any] = {
            "success": True,
            "match_count": len(union_ids),
            "resolved_symbol": symbol,
            "resolved_symbol_kind": requested_symbol_kind,
            "resolved_symbol_kind_input": symbol_kind,
            "candidates": descriptors,
            "truncated": max(0, len(sorted_union_ids) - max_candidates),
        }
        if scope_root_ids and scope_dropped:
            # [ap:WB323O] additive signal for the structured (non-raising)
            # callers (beacon.resolve): "no such symbol" and "matched only
            # outside your scope" are different answers to an agent.
            result["scope_filtered_count"] = scope_dropped
        return result

    if not union_ids:
        if scope_root_ids and scope_dropped:
            # [ap:WB323O] the snippet path names the scope so the agent can
            # widen or drop it (candidates-only mode never raises; it reports
            # match_count 0 + scope_filtered_count instead).
            scope_display = ", ".join(
                _short_handle_prefix(r) for r in scope_root_ids
            )
            raise NetworkError(
                "read_text_snippet_by_symbol: symbol "
                f"{symbol!r} matched {scope_dropped} node(s) but every "
                "candidate lies outside the requested root_handles scope "
                f"({scope_display}); widen or drop the scope."
            )
        raise NetworkError(
            "read_text_snippet_by_symbol: no matching node found for symbol "
            f"{symbol!r} (symbol_kind={symbol_kind!r})",
        )

    if len(union_ids) > 1:
        # Build a concise ambiguity report. Cap the emitted detail lines so
        # even a genuinely broad exact match cannot flood/crash the caller.
        details: list[str] = []
        max_ambiguity_details = 80
        sorted_union_ids = sorted(union_ids)
        for nid in sorted_union_ids[:max_ambiguity_details]:
            details.append(_render_candidate_line(_build_candidate_descriptor(nid)))
        if len(sorted_union_ids) > max_ambiguity_details:
            details.append(
                f"... truncated {len(sorted_union_ids) - max_ambiguity_details} additional candidates; "
                "refine file_path or symbol to narrow the search."
            )
        raise NetworkError(
            "read_text_snippet_by_symbol: symbol is ambiguous; candidates:\n"
            + "\n".join(details),
        )

    target_id = next(iter(union_ids))
    return ("resolved", target_id, nodes_by_id, requested_symbol_kind, node_to_file_path)


