        if ext in {".md", ".markdown"}:
            md_path_lines: list[str] = []
            if isinstance(note, str):
                in_block = False
                for line in note.splitlines():
                    stripped = line.strip()
                    if not in_block:
                        if stripped.startswith("MD_PATH:"):
                            in_block = True
                            continue
                    else:
                        if stripped == "---":
                            break
                        if stripped:
                            md_path_lines.append(stripped)

            if md_path_lines:
                try:
                    import importlib

                    client_dir = os.path.dirname(os.path.abspath(__file__))
                    wf_mcp_dir = os.path.dirname(client_dir)
                    mcp_servers_dir = os.path.dirname(wf_mcp_dir)
                    project_root = os.path.dirname(mcp_servers_dir)
                    if project_root not in sys.path:
                        sys.path.insert(0, project_root)

                    bos = importlib.import_module("beacon_obtain_code_snippet")
                except Exception as e:  # noqa: BLE001
                    raise NetworkError(
                        "Could not import beacon_obtain_code_snippet module for MD_PATH-based "
                        f"resolution; underlying error: {e}"
                    ) from e

                # Option C duplicate-sibling disambiguation: MD_PATH is a
                # semantic path, NOT unique (two sibling headings under one
                # parent may share the same text, e.g. two '## Dump Bay'). We
                # started from a concrete Workflowy UUID, so compute THIS node's
                # 1-based ordinal among same-name siblings under the same
                # parent, ordered by the cache 'priority' field (the canonical
                # Workflowy order; raw JSON order is NOT reliable). That ordinal
